def weak_quartets(k, N=120):
    M = N - 2 * k
    if M < 2:
        return 0
    # W = k * C(M, 2)
    return k * (M * (M - 1) // 2)

N = 120
results = {}
for k in range(1, 61):
    results[k] = weak_quartets(k, N)

# Find the maximum and where it occurs
max_w = 0
max_k = 0
for k, w in results.items():
